head.script:
scwin.trigger1_onclick = function(e) {
    var jsonData2 = [{
        "value": "a1",
        "depth": "1"
    }];
    dataList1.setRowJSON(27, jsonData2[0], false);
};
scwin.trigger2_onclick = function(e) {
    dataList1.insertRow(28);
};
scwin.__isAddedRow = function() {
    var tr = WebSquare.wUnit.getJq("#gridView1_body_tbody tr").not("tr.w2grid_hidedRow");
    var el = tr.get(tr.length - 1);
    return WebSquare.wUnit.getJq(el).find("td:first").text() == "31";
}
scwin.__showErrLog = function() {
    var err = WebSquare.logger.getErrorLog();
    return err ? true : false;
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_scrollY_div').scrollTop = 400");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "100");

    WebSquare.wUnit.addCommand("assert", "scwin.__isAddedRow()", "true");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_scrollY_div').scrollTop = 420");
    WebSquare.wUnit.addCommand("pause", "100");

    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView1').getTopRowIndex() == 21", "true");
    WebSquare.wUnit.addCommand("pause", "100");

    WebSquare.wUnit.addCommand("assert", "scwin.__showErrLog()", "false");
    WebSquare.wUnit.addCommand("pause", "100");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

